const QA='https://marshmallow-qa.com/iwk167hhzk9pfhl?t=gimhwG&utm_medium=url_text&utm_source=promotion';

let arTag='';
function render(){
  const el=document.getElementById('p-ar');
  if(!el) return;
  const jp=d=>{const [y,m,dd]=d.split('-'); return `${y}.${Number(m)}.${Number(dd)}`;};
  const tags=[...new Set(ARTICLES.map(a=>a.tag).filter(Boolean))];
  const list=ARTICLES.filter(a=>!arTag||a.tag===arTag);
  const href=a=>a.url?a.url:BASE+a.path;
  el.innerHTML=`
    <div class="lchips" id="artags">
      <button type="button" class="${arTag?'':'on'}" data-t="">すべて<small>${ARTICLES.length}</small></button>
      ${tags.map(t=>`<button type="button" class="${arTag===t?'on':''}" data-t="${esc(t)}">${esc(t)}<small>${
        ARTICLES.filter(a=>a.tag===t).length}</small></button>`).join('')}
    </div>
    <div class="arlist">
      ${list.map(a=>`
        <a class="arrow2" href="${esc(href(a))}" target="_blank" rel="noopener noreferrer">
          <span class="arthumb${a.pic?' pic':''}">${a.pic
            ? `<img src="${a.pic}" alt="" loading="lazy" decoding="async">`
            : (THUMB[a.tag]||THUMB._)}</span>
          <span class="arbody">
            <span class="arttl">${esc(a.title)}</span>
            <span class="armeta">${jp(a.date)}　${esc(a.who)}</span>
          </span>
          <span class="artag">${esc(a.tag)}</span>
        </a>`).join('')}
    </div>
    <p class="jknote">GEIDAY が書いている記事と、藝大生が note に書いた受験の記録です。押すと元の記事が開きます。
      <a href="${esc(QA)}" target="_blank" rel="noopener noreferrer">質問する</a></p>`;
  el.querySelectorAll('#artags button').forEach(b=>b.onclick=()=>{ arTag=b.dataset.t; render(); scrollTo({top:0}); });
}
window.renderArticles=render;
